const e=JSON.parse('{"key":"v-55b6d585","path":"/posts/lesson/CS161-computer-security/lec14-cookie.html","title":"","lang":"zh-CN","frontmatter":{"description":"什么是 CSRF 攻击？ CSRF（Cross-Site Request Forgery，跨站请求伪造）是一种攻击方式，攻击者通过诱导用户访问恶意链接或网站，伪造用户的身份并执行恶意操作。攻击者利用用户在已登录网站上的身份，借此向网站发送伪造的请求，而服务器无法识别出这些请求是否是用户本人的意图，从而可能导致敏感操作（如资金转账、修改个人信息等）被执行。 CSRF 攻击的工作原理： 用户已登录目标网站： 用户在银行或社交网站等已登录并保持会话（cookie未过期）。 攻击者构造恶意请求： 攻击者在其恶意网站或邮件中嵌入恶意链接或脚本。 用户点击恶意链接： 用户点击该链接时，浏览器会自动携带当前网站的会话cookie，向目标网站发送请求，伪装成用户发起的合法操作。 网站误认为请求来自用户： 由于请求携带有效的cookie，网站无法区分该请求是恶意的还是用户自发的，因此执行了非法操作。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/posts/lesson/CS161-computer-security/lec14-cookie.html"}],["meta",{"property":"og:site_name","content":"Code Building"}],["meta",{"property":"og:description","content":"什么是 CSRF 攻击？ CSRF（Cross-Site Request Forgery，跨站请求伪造）是一种攻击方式，攻击者通过诱导用户访问恶意链接或网站，伪造用户的身份并执行恶意操作。攻击者利用用户在已登录网站上的身份，借此向网站发送伪造的请求，而服务器无法识别出这些请求是否是用户本人的意图，从而可能导致敏感操作（如资金转账、修改个人信息等）被执行。 CSRF 攻击的工作原理： 用户已登录目标网站： 用户在银行或社交网站等已登录并保持会话（cookie未过期）。 攻击者构造恶意请求： 攻击者在其恶意网站或邮件中嵌入恶意链接或脚本。 用户点击恶意链接： 用户点击该链接时，浏览器会自动携带当前网站的会话cookie，向目标网站发送请求，伪装成用户发起的合法操作。 网站误认为请求来自用户： 由于请求携带有效的cookie，网站无法区分该请求是恶意的还是用户自发的，因此执行了非法操作。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-02-06T06:24:47.000Z"}],["meta",{"property":"article:modified_time","content":"2025-02-06T06:24:47.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2025-02-06T06:24:47.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":3,"title":"什么是 CSRF 攻击？","slug":"什么是-csrf-攻击","link":"#什么是-csrf-攻击","children":[]},{"level":3,"title":"如何防范 CSRF 攻击？","slug":"如何防范-csrf-攻击","link":"#如何防范-csrf-攻击","children":[]},{"level":3,"title":"总结：","slug":"总结","link":"#总结","children":[]}],"git":{"createdTime":1738823087000,"updatedTime":1738823087000,"contributors":[{"name":"zgjsxx","email":"119160625@qq.com","commits":1}]},"readingTime":{"minutes":5.12,"words":1537},"filePathRelative":"posts/lesson/CS161-computer-security/lec14-cookie.md","localizedDate":"2025年2月6日","excerpt":"<h3> <strong>什么是 CSRF 攻击？</strong></h3>\\n<p><strong>CSRF</strong>（Cross-Site Request Forgery，跨站请求伪造）是一种攻击方式，攻击者通过诱导用户访问恶意链接或网站，伪造用户的身份并执行恶意操作。攻击者利用用户在已登录网站上的身份，借此向网站发送伪造的请求，而服务器无法识别出这些请求是否是用户本人的意图，从而可能导致敏感操作（如资金转账、修改个人信息等）被执行。</p>\\n<h4> <strong>CSRF 攻击的工作原理：</strong></h4>\\n<ol>\\n<li><strong>用户已登录目标网站：</strong> 用户在银行或社交网站等已登录并保持会话（cookie未过期）。</li>\\n<li><strong>攻击者构造恶意请求：</strong> 攻击者在其恶意网站或邮件中嵌入恶意链接或脚本。</li>\\n<li><strong>用户点击恶意链接：</strong> 用户点击该链接时，浏览器会自动携带当前网站的会话cookie，向目标网站发送请求，伪装成用户发起的合法操作。</li>\\n<li><strong>网站误认为请求来自用户：</strong> 由于请求携带有效的cookie，网站无法区分该请求是恶意的还是用户自发的，因此执行了非法操作。</li>\\n</ol>","autoDesc":true}');export{e as data};
